export interface KeysetSort {
  readonly sortColumn: SQLiteColumn;
  readonly idColumn: SQLiteColumn;
}

/**
 * Predicate that resumes a descending listing after `cursor`. Returns
 * `undefined` for a first page or an unparseable cursor — a bad cursor
 * degrades to "start from the top", never to an error page.
 *
 * Rows are ordered `(sortColumn desc, idColumn desc)`, and `sortColumn` is
 * frequently non-unique — a bulk import or batch of notifications can share
 * the exact same timestamp. Comparing only `sortColumn` would silently drop
 * every row after the cursor that ties its value, so the id is used as a
 * tiebreaker: everything strictly older, plus same-instant rows that sort
 * after the cursor row's id.
 */
export function keysetPredicate(
  sort: KeysetSort,
  cursor: string | null | undefined,
): SQL | undefined {
  if (!cursor) return undefined;
  const decoded = decodeCursor(cursor);
  if (!decoded) return undefined;

  return or(
    lt(sort.sortColumn, decoded.sortValue),
    and(eq(sort.sortColumn, decoded.sortValue), lt(sort.idColumn, decoded.id)),
  );
}

